{"description": "Check EXIF and metadata of radiograph.jpg", "command": "python3 -c "
from PIL import Image
from PIL.ExifTags import TAGS

img = Image.open('radiograph.jpg')
info = img.info
print('Info:', info)
exif = img.getexif()
if exif:
    for k, v in exif.items():
        print(TAGS.get(k, k), v)
else:
    print('No exif')
""}

